public static Character firstNonRepeating(String input) {
    Map<Character, Long> countMap =
            input.chars()
                 .mapToObj(c -> (char) c)
                 .collect(Collectors.groupingBy(
                         Function.identity(),
                         LinkedHashMap::new,
                         Collectors.counting()
                 ));

    return countMap.entrySet()
                   .stream()
                   .filter(e -> e.getValue() == 1)
                   .map(Map.Entry::getKey)
                   .findFirst()
                   .orElse(null);
}
